package com.chatsystem.user.controller.report;
import com.chatsystem.shared.model.SpamReport;import com.chatsystem.shared.model.status.ReportStatus;import com.chatsystem.shared.service.ReportService;import com.chatsystem.user.navigation.*;import com.chatsystem.user.ui.cell.ReportCell;import javafx.collections.transformation.*;import javafx.fxml.FXML;import javafx.scene.control.*;import java.util.Comparator;
public final class SpamReportsController{private final ReportService reports;private final UserNavigator nav;private FilteredList<SpamReport>filtered;@FXML private TextField reportSearchField;@FXML private ChoiceBox<String>statusChoice;@FXML private ListView<SpamReport>reportList;@FXML private Label reportEmptyLabel;public SpamReportsController(ReportService r,UserNavigator n){reports=r;nav=n;}@FXML private void initialize(){filtered=new FilteredList<>(reports.getReports());var sorted=new SortedList<>(filtered,Comparator.comparing(SpamReport::getCreatedAt).reversed());reportList.setItems(sorted);reportList.setCellFactory(x->new ReportCell());statusChoice.getItems().setAll("Status: all","PENDING","REVIEWED","DISMISSED");statusChoice.getSelectionModel().selectFirst();statusChoice.getSelectionModel().selectedItemProperty().addListener((o,a,b)->search());}@FXML private void search(){String query=reportSearchField.getText()==null?"":reportSearchField.getText().strip().toLowerCase();String choice=statusChoice.getValue();filtered.setPredicate(r->(query.isEmpty()||r.getReason().toLowerCase().contains(query)||Long.toString(r.getId()).contains(query))&&("Status: all".equals(choice)||r.getStatus()==ReportStatus.valueOf(choice)));reportEmptyLabel.setVisible(filtered.isEmpty());reportEmptyLabel.setManaged(filtered.isEmpty());}@FXML private void create(){nav.showDialog("/fxml/dialogs/new-report.fxml","New report");}@FXML private void open(){var r=reportList.getSelectionModel().getSelectedItem();if(r!=null)nav.navigate(ViewRequest.report(r.getId()));}}
